\"\"\"Command-line interface for note-keeper.\"\"\"

from __future__ import annotations

import json
import os
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import click

DEFAULT_NOTES_PATH = Path.home() / \".notes.json\"


def load_notes(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    try:
        with path.open(\"r\", encoding=\"utf-8\") as file:
            data = json.load(file)
    except (json.JSONDecodeError, OSError):
        return []
    if not isinstance(data, list):
        return []
    return data


def save_notes(path: Path, notes: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open(\"w\", encoding=\"utf-8\") as file:
        json.dump(notes, file, indent=2, ensure_ascii=False)


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


@click.group()
@click.option(\"--file\", \"notes_file\", type=click.Path(path_type=Path), default=None)
@click.pass_context
def cli(ctx: click.Context, notes_file: Path | None) -> None:
    \"\"\"Keep short notes from the command line.\"\"\"
    ctx.ensure_object(dict)
    ctx.obj[\"path\"] = notes_file or Path(os.environ.get(\"NOTES_FILE\", DEFAULT_NOTES_PATH))


@cli.command()
@click.argument(\"text\")
@click.pass_context
def add(ctx: click.Context, text: str) -> None:
    \"\"\"Add a new note.\"\"\"
    path: Path = ctx.obj[\"path\"]
    notes = load_notes(path)
    note = {\"id\": len(notes) + 1, \"text\": text, \"created_at\": now_iso()}
    notes.append(note)
    save_notes(path, notes)
    click.echo(f\"Added note #{note['id']}: {text}\")


@cli.command(name=\"list\")
@click.pass_context
def list_notes(ctx: click.Context) -> None:
    \"\"\"List all notes.\"\"\"
    path: Path = ctx.obj[\"path\"]
    notes = load_notes(path)
    if not notes:
        click.echo(\"No notes yet.\")
        return
    for note in notes:
        click.echo(f\"#{note['id']} [{note.get('created_at', '?')}] {note['text']}\")


@cli.command()
@click.argument(\"query\")
@click.pass_context
def search(ctx: click.Context, query: str) -> None:
    \"\"\"Search notes for a substring.\"\"\"
    path: Path = ctx.obj[\"path\"]
    notes = load_notes(path)
    matches = [note for note in notes if query.lower() in note.get(\"text\", \"\").lower()]
    if not matches:
        click.echo(\"No matching notes.\")
        return
    for note in matches:
        click.echo(f\"#{note['id']} [{note.get('created_at', '?')}] {note['text']}\")


@cli.command()
@click.argument(\"note_id\", type=int)
@click.pass_context
def delete(ctx: click.Context, note_id: int) -> None:
    \"\"\"Delete a note by id.\"\"\"
    path: Path = ctx.obj[\"path\"]
    notes = load_notes(path)
    new_notes = [note for note in notes if note.get(\"id\") "'!= note_id]
    if len(new_notes) == len(notes):
        click.echo(f"Note #{note_id} not found.")
        raise click.Exit(1)
    save_notes(path, new_notes)
    click.echo(f"Deleted note #{note_id}.")


def main() -> None:
    cli()


if __name__ == "__main__":
    main()
EOF'

